 "content": "def transform(grid):
    H, W = len(grid), len(grid[0])

    def spans(n, get_line):
        result, start = [], 0
        for i in range(n):
            if len(set(get_line(i))) == 1:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(H, lambda r: grid[r])
    col_spans = spans(W, lambda c: [grid[r][c] for r in range(H)])
    output = []
    for r0, r1 in row_spans:
        row = []
        for c0, c1 in col_spans:
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            accents = sum(count for color, count in counts.items() if color != background)
            row.append(1 if accents == 2 else background)
        output.append(row)
    return output

